from pathlib import Path
root=Path(__file__).resolve().parent.parent
s=(root/'sprint-helper.js').read_text()
code=s[s.index('function s4tCommentSearchSpans('):]
test='''(async()=>{const wait=ms=>new Promise(r=>setTimeout(r,ms)),check=(v,m)=>{if(!v)throw Error(m)};try{
const card=document.createElement('div');card.dataset.testid='card-back';card.hidden=true;card.innerHTML='<header data-testid="card-back-header"></header>';document.body.appendChild(card);await Promise.resolve();await Promise.resolve();check(!!card.querySelector('.s4t-comment-navigator'),'toolbar mounts in initial empty header before reveal or comments');check(card.querySelectorAll('.s4t-comment-layout-toggle').length===2,'icons mount without timer');card.hidden=false;await wait(20);check(!!card.querySelector('.s4t-comment-navigator'),'search mounts on hidden card reveal');check(card.querySelectorAll('.s4t-comment-layout-toggle').length===2,'review and pen mount with search');const cover=document.createElement('button');cover.textContent='Cover';card.querySelector('header').appendChild(cover);await wait(180);check(cover.previousElementSibling.classList.contains('s4t-comment-search-slot'),'moves before late Cover');card.querySelector('header').innerHTML='<button>Cover</button>';await wait(20);check(card.querySelectorAll('.s4t-comment-layout-toggle').length===2,'navbar remount restores all controls');card.remove();await wait(30);document.body.appendChild(card);await wait(50);check(!!card.querySelector('.s4t-comment-navigator'),'reopened card has search');check(card.querySelectorAll('.s4t-comment-layout-toggle').length===2,'reopened card has exactly two icons');const pane=document.createElement('div');pane.style.cssText='height:120px;overflow-y:auto';pane.innerHTML='<h3>Comments &amp; activity</h3>'+Array.from({length:10},(_,i)=>'<div class="comment-container" style="height:70px">Comment '+i+'</div>').join('');const content=document.createElement('section');while(pane.firstChild)content.append(pane.firstChild);pane.append(content);const footer=document.createElement('div');footer.style.height='180px';pane.append(footer);card.appendChild(pane);await wait(150);const jumps=card.querySelector('.s4t-comment-jumps');check(jumps.parentElement===card,'controls do not change comments heading layout');check(getComputedStyle(jumps).position==='fixed','controls float');check(jumps.getBoundingClientRect().bottom<=pane.getBoundingClientRect().bottom,'controls inside comments bottom');check(jumps.querySelectorAll('button')[1].getBoundingClientRect().top>jumps.querySelector('button').getBoundingClientRect().top,'arrows stacked vertically');check(jumps.querySelector('[data-comment-jump="top"]').hidden,'top arrow hidden at start');check(!jumps.querySelector('[data-comment-jump="bottom"]').hidden,'bottom arrow visible at start');const originalArrowTop=jumps.getBoundingClientRect().top;window.matchMedia=()=>({matches:true});card.querySelector('[data-comment-jump="bottom"]').click();check(pane.scrollTop===pane.scrollHeight-pane.clientHeight,'bottom reaches scroll end including trailing content');pane.dispatchEvent(new Event('scroll'));await wait(50);check(Math.abs(jumps.getBoundingClientRect().top-originalArrowTop)<1,'arrow position stays fixed at bottom');check(jumps.querySelector('[data-comment-jump="bottom"]').hidden,'bottom arrow hidden at end');check(!jumps.querySelector('[data-comment-jump="top"]').hidden,'top arrow visible at end');card.querySelector('[data-comment-jump="top"]').click();check(pane.scrollTop===0,'top icon returns to comments heading');check(card.querySelectorAll('.s4t-comment-jump').length===2,'one pair of jump controls');
document.querySelector('#result').textContent='PASS: hidden reveal, immediate icons, late Cover, header remount and card reopen';}catch(e){document.querySelector('#result').textContent='FAIL: '+e.stack}})();'''
Path('/tmp/s4t-card-toolbar-ui.html').write_text('<html><head><style>'+(root/'sprint-helper.css').read_text()+'</style></head><body><pre id="result">RUNNING</pre><script>'+code+(root/'comment-layout.js').read_text()+test+'</script></body></html>')
